import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


# ----------------------------------------------------------------------
# Custom CUDA kernel for element-wise addition (reused from the example)
# ----------------------------------------------------------------------
elementwise_add_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void elementwise_add_kernel(const float* a, const float* b, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        out[idx] = a[idx] + b[idx];
    }
}

torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b) {
    auto size = a.numel();
    auto out = torch::zeros_like(a);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    elementwise_add_kernel<<<num_blocks, block_size>>>(a.data_ptr<float>(), b.data_ptr<float>(), out.data_ptr<float>(), size);

    return out;
}
"""

elementwise_add_cpp_source = "torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b);"
elementwise_add = load_inline(
    name="elementwise_add",
    cpp_sources=elementwise_add_cpp_source,
    cuda_sources=elementwise_add_source,
    functions=["elementwise_add_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[],
)

# ----------------------------------------------------------------------
# Custom CUDA kernel for upper‑triangular matrix multiplication
# ----------------------------------------------------------------------
matmul_upper_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void matmul_upper_kernel(const float* a, const float* b, float* c, int N) {
    // Each thread computes one output element C[row*N + col].
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < N * N) {
        int row = idx / N;
        int col = idx % N;
        if (row <= col) {               // upper triangle condition
            float sum = 0.0f;
            for (int k = max(row, col); k < N; ++k) {
                sum += a[row * N + k] * b[k * N + col];
            }
            c[idx] = sum;
        }
    }
}

torch::Tensor matmul_upper_cuda(torch::Tensor A, torch::Tensor B) {
    auto size = A.numel();
    // Allocate device memory for the output tensor
    float* out_ptr = new float[size * sizeof(float)];
    int N = A.size(0);
    const int BLOCK_SIZE = 256;
    int num_blocks = (N * N + BLOCK_SIZE - 1) / BLOCK_SIZE;

    matmul_upper_kernel<<<num_blocks, BLOCK_SIZE>>>(A.data_ptr<float>(), B.data_ptr<float>(), out_ptr, N);

    delete[] out_ptr;
    return torch::from_blob(out_ptr, (float*)out_ptr).contiguous().view(A.shape).to(torch.float32);
}
"""

matmul_upper_cuda_source = matmul_upper_kernel_source
matmul_upper = load_inline(
    name="matmul_upper",
    cpp_sources=matmul_upper_kernel_source,
    cuda_sources=matmul_upper_cuda_source,
    functions=["matmul_upper_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[],
)

class ModelNew(nn.Module):
    """
    Optimized version of the original `Model`.

    - Uses the custom CUDA operator `elementwise_add` (not needed for this model but available).
    - Uses a custom CUDA kernel `matmul_upper_cuda` to compute A @ B and then keeps only the upper triangular part.
    """

    def __init__(self) -> None:
        super(ModelNew, self).__init__()
        self.elementwise_add = elementwise_add
        self.matmul_upper = matmul_upper

    def forward(self, A, B):
        """
        Performs matrix multiplication for upper triangular matrices.

        Args:
            A (torch.Tensor): Upper triangular matrix of shape (N, N).
            B (torch.Tensor): Upper triangular matrix of shape (N, N).

        Returns:
            torch.Tensor: The product of A and B, also an upper triangular matrix of shape (N, N).
        """
        C = self.matmul_upper(A, B)   # custom CUDA kernel computes full product
        return torch.triu(C, diagonal=0)
